import db from '../../config/db';

export interface StaffRecord {
  id: number;
  email: string;
  password_hash: string;
  name: string;
  created_at: Date;
  updated_at: Date;
}

export class AuthRepository {
  public async findByEmail(email: string, excludeId?: number): Promise<StaffRecord | undefined> {
    const query = db<StaffRecord>('staff').where({ email });
    if (excludeId) {
      query.andWhereNot('id', excludeId);
    }
    return query.first();
  }

  public async findById(id: number): Promise<StaffRecord | undefined> {
    return db<StaffRecord>('staff').where({ id }).first();
  }

  public async create(data: Partial<StaffRecord>): Promise<StaffRecord> {
    const [staff] = await db<StaffRecord>('staff')
      .insert(data)
      .returning('*');
    return staff;
  }

  public async update(id: number, data: Partial<StaffRecord>): Promise<StaffRecord | undefined> {
    const [updated] = await db<StaffRecord>('staff')
      .where({ id })
      .update({
        ...data,
        updated_at: new Date()
      })
      .returning('*');
    return updated;
  }

  public async delete(id: number): Promise<boolean> {
    const affected = await db('staff').where({ id }).del();
    return affected > 0;
  }
}

import bcrypt from 'bcryptjs';
import jwt, { Secret, SignOptions } from 'jsonwebtoken';
import { AuthRepository, StaffRecord } from './auth.repository';
import { ENV } from '../../config/env';
import { AppError } from '../../utils/appError';

export interface LoginDTO {
  email: string;
  password: string;
}

export interface RegisterDTO {
  email: string;
  password: string;
  name: string;
}

export interface UpdateProfileDTO {
  email?: string;
  password?: string;
  name?: string;
}

export interface StaffProfile {
  id: number;
  email: string;
  name: string;
  created_at: Date;
  updated_at: Date;
}

export interface AuthResponse {
  token: string;
  staff: StaffProfile;
}

export class AuthService {
  private authRepo: AuthRepository;

  constructor() {
    this.authRepo = new AuthRepository();
  }

  public async register(dto: RegisterDTO): Promise<AuthResponse> {
    const existing = await this.authRepo.findByEmail(dto.email);
    if (existing) {
      throw new AppError(`Staff with email ${dto.email} already exists`, 400);
    }

    const password_hash = await bcrypt.hash(dto.password, 10);
    const staff = await this.authRepo.create({
      email: dto.email,
      password_hash,
      name: dto.name
    });

    const profile = this.sanitizeStaff(staff);
    const token = this.generateToken(profile);

    return {
      token,
      staff: profile
    };
  }

  public async login(dto: LoginDTO): Promise<AuthResponse> {
    const staff = await this.authRepo.findByEmail(dto.email);

    if (!staff) {
      throw new AppError('Invalid email or password', 401);
    }

    const isMatch = await bcrypt.compare(dto.password, staff.password_hash);
    if (!isMatch) {
      throw new AppError('Invalid email or password', 401);
    }

    const profile = this.sanitizeStaff(staff);
    const token = this.generateToken(profile);

    return {
      token,
      staff: profile
    };
  }

  public async getProfile(userId: number): Promise<StaffProfile> {
    const staff = await this.authRepo.findById(userId);
    if (!staff) {
      throw new AppError('Staff profile not found', 404);
    }
    return this.sanitizeStaff(staff);
  }

  public async updateProfile(userId: number, dto: UpdateProfileDTO): Promise<StaffProfile> {
    const current = await this.authRepo.findById(userId);
    if (!current) {
      throw new AppError('Staff profile not found', 404);
    }

    const updateData: Partial<StaffRecord> = {};

    if (dto.name) {
      updateData.name = dto.name;
    }

    if (dto.email && dto.email !== current.email) {
      const existing = await this.authRepo.findByEmail(dto.email, userId);
      if (existing) {
        throw new AppError(`Email ${dto.email} is already in use`, 400);
      }
      updateData.email = dto.email;
    }

    if (dto.password) {
      updateData.password_hash = await bcrypt.hash(dto.password, 10);
    }

    const updated = await this.authRepo.update(userId, updateData);
    if (!updated) {
      throw new AppError('Failed to update staff profile', 400);
    }

    return this.sanitizeStaff(updated);
  }

  public async deleteProfile(userId: number): Promise<void> {
    const current = await this.authRepo.findById(userId);
    if (!current) {
      throw new AppError('Staff profile not found', 404);
    }

    const deleted = await this.authRepo.delete(userId);
    if (!deleted) {
      throw new AppError('Failed to delete staff profile', 400);
    }
  }

  private sanitizeStaff(staff: StaffRecord): StaffProfile {
    return {
      id: staff.id,
      email: staff.email,
      name: staff.name,
      created_at: staff.created_at,
      updated_at: staff.updated_at
    };
  }

  private generateToken(profile: { id: number; email: string; name: string }): string {
    const payload = {
      id: profile.id,
      email: profile.email,
      name: profile.name
    };
    const secret: Secret = ENV.JWT.SECRET;
    const options: SignOptions = {
      expiresIn: ENV.JWT.EXPIRES_IN as SignOptions['expiresIn']
    };
    return jwt.sign(payload, secret, options);
  }
}

import { Request, Response, NextFunction } from 'express';
import { AuthService } from './auth.service';
import { ResponseUtil } from '../../utils/apiResponse';

export class AuthController {
  private authService: AuthService;

  constructor() {
    this.authService = new AuthService();
  }

  public register = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const result = await this.authService.register(req.body);
      ResponseUtil.success(res, result, 'Staff registered successfully', 201);
    } catch (error) {
      next(error);
    }
  };

  public login = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const result = await this.authService.login(req.body);
      ResponseUtil.success(res, result, 'Login successful');
    } catch (error) {
      next(error);
    }
  };

  public getProfile = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const userId = req.user!.id;
      const profile = await this.authService.getProfile(userId);
      ResponseUtil.success(res, profile, 'Staff profile retrieved successfully');
    } catch (error) {
      next(error);
    }
  };

  public updateProfile = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const userId = req.user!.id;
      const profile = await this.authService.updateProfile(userId, req.body);
      ResponseUtil.success(res, profile, 'Staff profile updated successfully');
    } catch (error) {
      next(error);
    }
  };

  public deleteProfile = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const userId = req.user!.id;
      await this.authService.deleteProfile(userId);
      ResponseUtil.success(res, null, 'Staff profile deleted successfully');
    } catch (error) {
      next(error);
    }
  };
}

import { Router } from 'express';
